package com.myaaptha.domain.trust;

import com.fasterxml.jackson.databind.ObjectMapper;
import com.myaaptha.domain.contacts.AddressBookService;
import com.myaaptha.domain.privacy.UserBlockRepository;
import com.myaaptha.domain.profile.UserProfileRepository;
import com.myaaptha.domain.social.*;
import com.myaaptha.domain.social.model.SocialPostEntity;
import com.myaaptha.domain.user.UserRepository;
import com.myaaptha.platform.security.FieldEncryption;
import jakarta.validation.Valid;
import jakarta.validation.constraints.*;
import java.net.URI;
import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.security.Principal;
import java.time.Instant;
import java.util.*;
import org.springframework.http.HttpStatus;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.jdbc.core.namedparam.NamedParameterJdbcTemplate;
import org.springframework.jdbc.support.GeneratedKeyHolder;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.web.bind.annotation.*;
import org.springframework.web.server.ResponseStatusException;

@RestController @RequestMapping("/api/advisors")
public class AdvisorController {
 private static final Map<String,String> DEFAULTS=new LinkedHashMap<>();
 static{DEFAULTS.put("PERSONAL","Personal");DEFAULTS.put("HEALTH_FITNESS","Health & fitness");DEFAULTS.put("WEALTH","Wealth");DEFAULTS.put("EDUCATION_CAREER","Education & career");DEFAULTS.put("LAW","Law");DEFAULTS.put("SPORTS","Sports");DEFAULTS.put("ARTS","Arts");DEFAULTS.put("TECHNOLOGY","Technology");DEFAULTS.put("BUSINESS","Business");DEFAULTS.put("RELATIONSHIPS","Relationships");DEFAULTS.put("COMMUNITY","Community");DEFAULTS.put("OTHER","Other");}
 public record Category(String key,String name,long people,boolean custom){}
 public record Person(long id,String kind,Long memberId,Long contactId,String name,String photo,String url,String notes,List<String> categories,boolean followPosts,long version){}
 public record Page(List<Person> items,Long nextCursor){}
 public record Input(Long memberId,Long contactId,@Size(max=200) String name,@Size(max=2048) String url,@Size(max=2000) String notes,@NotNull @Size(min=1,max=1000) List<@NotBlank @Size(max=80) String> categories,Boolean followPosts,Long version){}
 public record CategoryInput(@NotBlank @Size(max=100) String name){}
 public record Details(String name,String url,String notes){}
 public record Feed(List<SocialDtos.Post> items,String nextCursor,boolean hasNext){}
 public record Member(long id,String name,String photo){}
 private record Cursor(Instant at,String kind,long id){}
 private final JdbcTemplate db;private final ObjectMapper json;private final FieldEncryption encryption;private final AddressBookService book;private final UserRepository users;private final UserProfileRepository profiles;private final UserBlockRepository blocks;private final SocialPostRepository posts;private final SocialService social;
 public AdvisorController(JdbcTemplate db,ObjectMapper json,FieldEncryption encryption,AddressBookService book,UserRepository users,UserProfileRepository profiles,UserBlockRepository blocks,SocialPostRepository posts,SocialService social){this.db=db;this.json=json;this.encryption=encryption;this.book=book;this.users=users;this.profiles=profiles;this.blocks=blocks;this.posts=posts;this.social=social;}
 private long user(Principal p){return Long.parseLong(p.getName());}
 @GetMapping("/categories") public List<Category> categories(Principal p){return categories(user(p));}
 private List<Category> categories(long owner){Map<String,String> names=new LinkedHashMap<>(DEFAULTS);db.query("SELECT category_key,name FROM advisor_categories WHERE user_id=? ORDER BY name",rs->{names.put(rs.getString(1),rs.getString(2));},owner);Map<String,Long> counts=new HashMap<>();db.query("SELECT category_key,COUNT(*) FROM advisor_category_members WHERE user_id=? GROUP BY category_key",rs->{counts.put(rs.getString(1),rs.getLong(2));},owner);return names.entrySet().stream().map(e->new Category(e.getKey(),e.getValue(),counts.getOrDefault(e.getKey(),0L),!DEFAULTS.containsKey(e.getKey()))).toList();}
 @PostMapping("/categories") @Transactional public Category category(Principal p,@Valid @RequestBody CategoryInput request){long owner=user(p);lock(owner);String name=request.name().trim();for(var existing:categories(owner))if(existing.name().equalsIgnoreCase(name))return existing;String key="c-"+UUID.randomUUID();db.update("INSERT INTO advisor_categories(user_id,category_key,name) VALUES(?,?,?)",owner,key,name);return new Category(key,name,0,true);}
 @GetMapping("/members") public List<Member> search(Principal p,@RequestParam String q){if(q.length()>200)throw bad("Search text is too long");if(q.trim().length()<2)return List.of();long owner=user(p);String pattern="%"+q.trim().toLowerCase(Locale.ROOT).replace("!","!!").replace("%","!%").replace("_","!_")+"%";return users.discoverPeople(owner,pattern,org.springframework.data.domain.PageRequest.of(0,50)).stream().filter(u->"ACTIVE".equals(u.getAccountStatus())&&!"MANAGED".equals(u.getIdentityType())&&!blocks.blockedEitherWay(owner,u.getId())).map(u->new Member(u.getId(),name(u.getId()),photo(u.getId()))).toList();}
 @GetMapping public Page list(Principal p,@RequestParam(defaultValue="ALL") String category,@RequestParam(defaultValue="0") long afterId){long owner=user(p);checkCategory(owner,category);if(afterId<0)throw bad("Invalid page");String filter=category.equals("ALL")?"":" AND EXISTS(SELECT 1 FROM advisor_category_members m WHERE m.user_id=a.user_id AND m.advisor_id=a.id AND m.category_key=?)";List<Object> args=new ArrayList<>(List.of(owner,afterId));if(!category.equals("ALL"))args.add(category);var ids=db.queryForList("SELECT a.id FROM advisor_people a WHERE a.user_id=? AND a.id>?"+filter+" ORDER BY a.id LIMIT 51",Long.class,args.toArray());var page=ids.stream().limit(50).toList();return new Page(page.stream().map(id->required(owner,id)).toList(),ids.size()>50?page.getLast():null);}
 @PostMapping @Transactional public Person add(Principal p,@Valid @RequestBody Input input){long owner=user(p);lock(owner);String kind;String identity;Details details;boolean follows=false;if(input.memberId()!=null){if(input.contactId()!=null)throw bad("Choose a member or a private contact");requireMember(owner,input.memberId());kind="MEMBER";identity="m:"+input.memberId();details=new Details("",null,clean(input.notes()));follows=input.followPosts()==null||input.followPosts();}else if(input.contactId()!=null){if(book.entries(owner,List.of(input.contactId())).isEmpty())throw missing();kind="CONTACT";identity="c:"+input.contactId();details=new Details("",null,clean(input.notes()));}else{if(input.name()==null||input.name().isBlank())throw bad("Enter the person's name");String url=url(input.url());kind="EXTERNAL";identity=url==null?"n:"+UUID.randomUUID():"u:"+hash(url);details=new Details(input.name().trim(),url,clean(input.notes()));}ensureCategories(owner,input.categories());var existing=db.queryForList("SELECT id FROM advisor_people WHERE user_id=? AND identity_key=?",Long.class,owner,identity);long id;if(!existing.isEmpty()){id=existing.getFirst();db.update("UPDATE advisor_people SET version=version+1 WHERE user_id=? AND id=?",owner,id);}else{var key=new GeneratedKeyHolder();String payload=encode(details);boolean follow=follows;db.update(c->{var s=c.prepareStatement("INSERT INTO advisor_people(user_id,identity_key,kind,member_user_id,contact_id,details,follow_posts) VALUES(?,?,?,?,?,?,?)",new String[]{"id"});s.setLong(1,owner);s.setString(2,identity);s.setString(3,kind);if(input.memberId()==null)s.setNull(4,java.sql.Types.BIGINT);else s.setLong(4,input.memberId());if(input.contactId()==null)s.setNull(5,java.sql.Types.BIGINT);else s.setLong(5,input.contactId());s.setString(6,payload);s.setBoolean(7,follow);return s;},key);id=Objects.requireNonNull(key.getKey()).longValue();}for(String category:new LinkedHashSet<>(input.categories()))if(db.queryForObject("SELECT COUNT(*) FROM advisor_category_members WHERE advisor_id=? AND category_key=?",Integer.class,id,category)==0)db.update("INSERT INTO advisor_category_members(user_id,advisor_id,category_key) VALUES(?,?,?)",owner,id,category);return required(owner,id);}
 @PostMapping("/{id}/update") @Transactional public Person update(Principal p,@PathVariable long id,@Valid @RequestBody Input input){long owner=user(p);lock(owner);Person current=required(owner,id);if(input.version()==null||input.version()!=current.version())throw new ResponseStatusException(HttpStatus.CONFLICT,"This advisor changed on another device. Refresh before editing");ensureCategories(owner,input.categories());Details details=new Details(current.kind().equals("EXTERNAL")?Objects.requireNonNullElse(input.name(),current.name()).trim():"",current.kind().equals("EXTERNAL")?url(input.url()):null,clean(input.notes()));if(current.kind().equals("EXTERNAL")&&details.name().isBlank())throw bad("Enter the person's name");boolean follows=current.kind().equals("MEMBER")&&(input.followPosts()==null?current.followPosts():input.followPosts());if(follows)requireMember(owner,current.memberId());String identity=current.kind().equals("EXTERNAL")?(details.url()==null?"n:"+UUID.randomUUID():"u:"+hash(details.url())):null;if(identity!=null&&db.queryForObject("SELECT COUNT(*) FROM advisor_people WHERE user_id=? AND identity_key=? AND id<>?",Integer.class,owner,identity,id)>0)throw new ResponseStatusException(HttpStatus.CONFLICT,"This profile is already in your advisors");db.update("UPDATE advisor_people SET details=?,follow_posts=?,version=version+1 WHERE user_id=? AND id=?",encode(details),follows,owner,id);if(identity!=null)db.update("UPDATE advisor_people SET identity_key=? WHERE user_id=? AND id=?",identity,owner,id);db.update("DELETE FROM advisor_category_members WHERE advisor_id=? AND user_id=?",id,owner);for(String category:new LinkedHashSet<>(input.categories()))db.update("INSERT INTO advisor_category_members(user_id,advisor_id,category_key) VALUES(?,?,?)",owner,id,category);return required(owner,id);}
 @PostMapping("/{id}/delete") @Transactional public void remove(Principal p,@PathVariable long id){long owner=user(p);required(owner,id);db.update("DELETE FROM advisor_people WHERE user_id=? AND id=?",owner,id);}
 @GetMapping("/feed") public Feed feed(Principal p,@RequestParam(defaultValue="ALL") String category,@RequestParam(required=false) String before,@RequestParam(defaultValue="false") boolean saved){long owner=user(p);checkCategory(owner,category);String filter=category.equals("ALL")?"":" AND EXISTS(SELECT 1 FROM advisor_category_members m WHERE m.advisor_id=a.id AND m.user_id=a.user_id AND m.category_key=?)";List<Object> args=new ArrayList<>(List.of(owner));if(!category.equals("ALL"))args.add(category);Set<Long> actors=new HashSet<>(db.queryForList("SELECT DISTINCT a.member_user_id FROM advisor_people a WHERE a.user_id=? AND a.follow_posts=TRUE AND a.member_user_id IS NOT NULL"+filter,Long.class,args.toArray()));actors.removeIf(id->blocks.blockedEitherWay(owner,id));if(actors.isEmpty())return new Feed(List.of(),null,false);Cursor cursor=cursor(before);List<SocialDtos.Post> result=new ArrayList<>();Set<Long> seen=new HashSet<>();boolean more=true;NamedParameterJdbcTemplate named=new NamedParameterJdbcTemplate(db);
  for(int scan=0;scan<10&&result.size()<20&&more;scan++){var params=new HashMap<String,Object>();params.put("actors",actors);params.put("at",java.sql.Timestamp.from(cursor.at()));params.put("kind",cursor.kind());params.put("event",cursor.id());var events=named.queryForList("SELECT * FROM (SELECT id AS event_id,id AS post_id,author_user_id AS actor_id,created_at AS activity_at,'POST' AS kind FROM social_posts WHERE author_user_id IN (:actors) UNION ALL SELECT id AS event_id,post_id,user_id AS actor_id,created_at AS activity_at,'REPOST' AS kind FROM social_reposts WHERE user_id IN (:actors)) e WHERE activity_at<:at OR (activity_at=:at AND (kind<:kind OR (kind=:kind AND event_id<:event))) ORDER BY activity_at DESC,kind DESC,event_id DESC LIMIT 100",params);if(events.isEmpty()){more=false;break;}for(var event:events){long eventId=((Number)event.get("event_id")).longValue(),postId=((Number)event.get("post_id")).longValue(),actor=((Number)event.get("actor_id")).longValue();String kind=(String)event.get("kind");Instant at=instant(event.get("activity_at"));cursor=new Cursor(at,kind,eventId);SocialPostEntity post=posts.findById(postId).orElse(null);if(post==null||!social.canView(owner,post)||!seen.add(postId))continue;var dto=social.post(owner,postId);if(saved&&!dto.savedByMe())continue;result.add(kind.equals("REPOST")?dto.withRepost(actor,name(actor),at):dto);if(result.size()==20)break;}if(events.size()<100&&((Number)events.getLast().get("event_id")).longValue()==cursor.id()&&events.getLast().get("kind").equals(cursor.kind()))more=false;}
  return new Feed(result,more?encodeCursor(cursor):null,more);
 }
 private Person required(long owner,long id){var rows=db.queryForList("SELECT * FROM advisor_people WHERE user_id=? AND id=?",owner,id);if(rows.isEmpty())throw missing();var row=rows.getFirst();Details details=decode((String)row.get("details"));Long member=(Long)row.get("member_user_id"),contact=(Long)row.get("contact_id");String kind=(String)row.get("kind"),name=details.name();if(member!=null)name=name(member);if(contact!=null){var contacts=book.entries(owner,List.of(contact));name=contacts.isEmpty()?"Private contact":contacts.getFirst().displayName();}var categories=db.queryForList("SELECT category_key FROM advisor_category_members WHERE user_id=? AND advisor_id=? ORDER BY category_key",String.class,owner,id);return new Person(id,kind,member,contact,name,member==null?null:photo(member),details.url(),details.notes(),categories,Boolean.TRUE.equals(row.get("follow_posts")),((Number)row.get("version")).longValue());}
 private void ensureCategories(long owner,List<String> keys){Map<String,String> allowed=new HashMap<>();for(var category:categories(owner))allowed.put(category.key(),category.name());for(String key:new LinkedHashSet<>(keys)){if(!allowed.containsKey(key))throw bad("Choose your own advisor categories");if(db.queryForObject("SELECT COUNT(*) FROM advisor_categories WHERE user_id=? AND category_key=?",Integer.class,owner,key)==0)db.update("INSERT INTO advisor_categories(user_id,category_key,name) VALUES(?,?,?)",owner,key,allowed.get(key));}}
 private void checkCategory(long owner,String category){if(!category.equals("ALL")&&categories(owner).stream().noneMatch(c->c.key().equals(category)))throw bad("Choose an advisor category");}
 private void requireMember(long owner,long member){var user=users.findById(member).orElseThrow(AdvisorController::missing);if(owner==member||!"ACTIVE".equals(user.getAccountStatus())||"MANAGED".equals(user.getIdentityType())||blocks.blockedEitherWay(owner,member))throw bad("Choose an active MyAaptha member you can connect with");}
 private String name(long id){var user=users.findById(id).orElseThrow(AdvisorController::missing);String name=(Objects.requireNonNullElse(user.getFirstName(),"")+" "+Objects.requireNonNullElse(user.getSurname(),"")).trim();return name.isBlank()?user.getUsername():name;}
 private String photo(long id){return profiles.findById(id).map(p->p.getProfilePhoto()).orElse(null);}
 private void lock(long owner){db.queryForObject("SELECT id FROM users WHERE id=? FOR UPDATE",Long.class,owner);}
 private String encode(Details details){try{return encryption.encrypt(json.writeValueAsString(details));}catch(Exception e){throw new IllegalStateException("Advisor details could not be saved",e);}}
 private Details decode(String value){try{return json.readValue(encryption.decrypt(value),Details.class);}catch(Exception e){throw new IllegalStateException("Advisor details could not be read",e);}}
 private static String url(String raw){if(raw==null||raw.isBlank())return null;try{URI uri=URI.create(raw.trim());if(!"https".equalsIgnoreCase(uri.getScheme())||uri.getHost()==null||uri.getUserInfo()!=null)throw new IllegalArgumentException();return uri.toString();}catch(Exception e){throw bad("Use a complete HTTPS profile link");}}
 private static String clean(String text){return text==null?"":text.trim();}
 private static Cursor cursor(String token){if(token==null)return new Cursor(Instant.parse("9999-01-01T00:00:00Z"),"ZZZ",Long.MAX_VALUE);try{if(token.length()>200)throw new IllegalArgumentException();String[] parts=new String(Base64.getUrlDecoder().decode(token),StandardCharsets.UTF_8).split("\\|",-1);if(parts.length!=3||!Set.of("POST","REPOST").contains(parts[1]))throw new IllegalArgumentException();long id=Long.parseLong(parts[2]);if(id<1)throw new IllegalArgumentException();return new Cursor(Instant.parse(parts[0]),parts[1],id);}catch(Exception e){throw bad("Refresh the advisor feed to load a valid page");}}
 private static String encodeCursor(Cursor cursor){return Base64.getUrlEncoder().withoutPadding().encodeToString((cursor.at()+"|"+cursor.kind()+"|"+cursor.id()).getBytes(StandardCharsets.UTF_8));}
 private static Instant instant(Object value){return value instanceof java.time.OffsetDateTime at?at.toInstant():((java.sql.Timestamp)value).toInstant();}
 private static String hash(String value){try{return HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(value.getBytes(StandardCharsets.UTF_8)));}catch(Exception e){throw new IllegalStateException(e);}}
 private static ResponseStatusException bad(String text){return new ResponseStatusException(HttpStatus.BAD_REQUEST,text);}
 private static ResponseStatusException missing(){return new ResponseStatusException(HttpStatus.NOT_FOUND,"Advisor not found");}
}
